window.__SD=(window.__SD||[]).concat([{"slug": "allan-dafoe", "name": "Allan Dafoe", "category": "governance-policy", "current_role": "Senior Director, Frontier Strategy and Governance, and Distinguished Research Scientist, Google DeepMind (as of 2026)", "orgs_history": ["Founding Director, then President, Centre for the Governance of AI (GovAI), Oxford (2018–2023)", "Associate Professor, University of Oxford (2018–21)", "Assistant Professor of Political Science, Yale (2012–18)", "Founder and Trustee, Cooperative AI Foundation", "Senior Advisor and Visiting Fellow, Oxford Martin AI Governance Initiative"], "country": "", "known_for": "Founded the field of AI governance as an academic discipline (GovAI) and now leads frontier strategy and governance at Google DeepMind.", "bio": "Allan Dafoe is a political scientist who helped create AI governance as a research field. A former Yale professor working on great-power peace, technological determinism and causal inference, he moved to Oxford's Future of Humanity Institute and founded the Centre for the Governance of AI (GovAI), now an independent nonprofit that has trained much of today's AI-policy workforce. He also founded the Cooperative AI Foundation, which argues that cooperative intelligence in AI may matter as much as alignment. Dafoe joined DeepMind in 2021 and now leads its Frontier Strategy and Governance team as Senior Director; he co-led successive versions of Google DeepMind's Frontier Safety Framework (2024–2026), the company's protocols for identifying and mitigating severe risks such as cyber, bio and loss-of-control capabilities. His 2019 paper with Remco Zwetsloot introduced 'structural risk' alongside misuse and accident risk. On his homepage he states that he believes 'the governance of AI is the most important issue of the century'.", "key_ideas": ["AI governance as a field", "structural risks (beyond misuse and accidents)", "cooperative AI", "technological determinism and competition", "frontier safety frameworks / dangerous-capability evaluations", "multilayered governance of frontier AI"], "key_works": [{"title": "AI Governance: A Research Agenda", "year": 2018, "url": "https://www.governance.ai/research"}, {"title": "Thinking About Risks From AI: Accidents, Misuse and Structure (with R. Zwetsloot, Lawfare)", "year": 2019, "url": "https://www.lawfaremedia.org/article/thinking-about-risks-ai-accidents-misuse-and-structure"}, {"title": "Open Problems in Cooperative AI", "year": 2020, "url": "https://arxiv.org/abs/2012.08630"}, {"title": "Updating the Frontier Safety Framework (Google DeepMind, co-author)", "year": 2025, "url": "https://deepmind.google/blog/updating-the-frontier-safety-framework/"}], "quotes": [{"text": "I believe the governance of AI is the most important issue of the century.", "context": "Personal homepage (current)", "source_url": "https://www.allandafoe.com/"}, {"text": "You want to channel energy where it will be high leverage, where it will have lasting impact — rather than in these settings where the structure will resist your pressure with an equal counterpressure.", "context": "80,000 Hours podcast (Feb 2025), pull quote", "source_url": "https://80000hours.org/podcast/episodes/allan-dafoe-unstoppable-technology-human-agency-agi/"}, {"text": "I would say Google DeepMind and Google’s perspective is that the governance of frontier AI ultimately needs to be multilayered. There will be an important role for government regulations, for third-party evaluations, and other sort of nonprofit input and other external assessment of the properties of frontier models.", "context": "80,000 Hours podcast (Feb 2025)", "source_url": "https://80000hours.org/podcast/episodes/allan-dafoe-unstoppable-technology-human-agency-agi/"}, {"text": "If AI systems can cooperate with each other much better than they can cooperate with humans, then maybe we get left behind as trading partners and as decision makers in a world where the AI civilisation can more effectively cooperate within machine time speeds and using the AI vocabulary that’s emerged.", "context": "80,000 Hours podcast (Feb 2025), on the exclusionary effects of cooperative AI", "source_url": "https://80000hours.org/podcast/episodes/allan-dafoe-unstoppable-technology-human-agency-agi/"}], "interviews": [{"title": "Allan Dafoe on why technology is unstoppable & how to shape AI development anyway", "outlet": "80,000 Hours", "year": 2025, "url": "https://80000hours.org/podcast/episodes/allan-dafoe-unstoppable-technology-human-agency-agi/"}, {"title": "Agency over AI? Allan Dafoe on Technological Determinism & DeepMind's Safety Plans", "outlet": "The Cognitive Revolution", "year": 2025, "url": "https://www.cognitiverevolution.ai/agency-over-ai-allan-dafoe-on-technological-determinism-deepminds-safety-plans-from-80000-hours/"}, {"title": "AI Talks (collected talks and interviews)", "outlet": "allandafoe.com", "year": 2025, "url": "https://www.allandafoe.com/ai-talks"}], "links": {"website": "https://www.allandafoe.com/", "x": "", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": "", "honours": [], "photo": "allan-dafoe.jpg"}, {"slug": "helen-toner", "name": "Helen Toner", "category": "governance-policy", "current_role": "Executive Director, Center for Security and Emerging Technology (CSET), Georgetown University (interim from Sept 2025; named permanent June 2026)", "orgs_history": ["OpenAI board member (2021–Nov 2023)", "CSET Director of Strategy and Foundational Research Grants (2019–2025)", "Research Affiliate, Centre for the Governance of AI, Oxford (2018)", "Senior Research Analyst, Open Philanthropy (2016–18)", "GiveWell"], "country": "Australia", "known_for": "Former OpenAI board member who voted to remove Sam Altman in 2023; now leads Georgetown's CSET and is one of Washington's most-quoted AI-safety voices.", "bio": "Helen Toner (born 1992) is an Australian AI-policy researcher. After working at GiveWell and Open Philanthropy advising on AI policy and grantmaking, and a stint in Beijing studying China's AI ecosystem, she helped found Georgetown University's Center for Security and Emerging Technology (CSET) in 2019 as Director of Strategy. She joined OpenAI's nonprofit board in 2021 and was one of the directors who removed Sam Altman as CEO in November 2023, saying later that the board had not been kept properly informed; she left the board when Altman returned. She became CSET's interim executive director in September 2025 and permanent executive director in mid-2026. In 2026 she testified to the Senate Judiciary Committee on US–China AI competition and distillation, and became a leading commentator on the year's rogue-agent incidents and OpenAI's training pause, calling for federal disclosure rules, independent third-party audits and government 'emergency intervention powers' over frontier AI. TIME named her one of the 100 most influential people in AI in 2024.", "key_ideas": ["AI and national security", "US–China AI competition", "frontier AI transparency and incident reporting", "independent third-party auditing", "emergency intervention powers", "governing AI under uncertainty"], "key_works": [{"title": "How to govern AI — even if it's hard to predict (TED talk)", "year": 2024, "url": "https://www.ted.com/talks/helen_toner_how_to_govern_ai_even_if_it_s_hard_to_predict"}, {"title": "Written Testimony for the Senate Judiciary Committee", "year": 2026, "url": "https://cset.georgetown.edu/wp-content/uploads/Senate-Judiciary-written-testimony-2026-04-22-Toner.pdf"}, {"title": "Rising Tide (Substack)", "year": 2025, "url": "https://helentoner.substack.com/"}], "quotes": [{"text": "Our techniques for making A.I. that is more capable, smarter, more sophisticated, are working much better than our techniques for making A.I. that reliably does what we want it to do and reliably stays within the constraints we’ve set.", "context": "The Ezra Klein Show, The New York Times (18 Aug 2026), as quoted by CSET", "source_url": "https://cset.georgetown.edu/article/the-a-i-s-are-already-out-of-control/"}, {"text": "Right now…the winner of any AI race between the U.S. and China is the AI. We need to be working to make sure that is not the case.", "context": "Exchange with Sen. Josh Hawley, Senate Judiciary Committee hearing, 22 April 2026", "source_url": "https://cset.georgetown.edu/article/cset-director-helen-toner-testifies-before-senate-judiciary-committee"}, {"text": "I think it is very important that the U.S. AI sector remains ahead of the Chinese AI sector, but if that’s at the expense of AI overrunning the entire planet, then that hasn’t benefitted us.", "context": "Same Senate hearing (April 2026)", "source_url": "https://cset.georgetown.edu/article/cset-director-helen-toner-testifies-before-senate-judiciary-committee"}, {"text": "What we're seeing here is really something that the industry has expected for a long time in theory but is now starting to materialize in practice, which is the AI systems we're building are so capable, they can do so many different things, that it's actually quite difficult for us to keep testing them in a way that is controlled and that we're confident we have a handle on.", "context": "NPR Morning Edition, on OpenAI pausing training of its latest model (29 Sept 2026)", "source_url": "https://www.npr.org/2026/09/29/nx-s1-5983549/openai-stops-training-latests-models-citing-safety-concerns"}], "interviews": [{"title": "How to govern AI — even if it's hard to predict", "outlet": "TED", "year": 2024, "url": "https://www.ted.com/talks/helen_toner_how_to_govern_ai_even_if_it_s_hard_to_predict"}, {"title": "The A.I.s Are Already Out of Control (The Ezra Klein Show)", "outlet": "The New York Times", "year": 2026, "url": "https://www.nytimes.com/2026/08/18/opinion/ezra-klein-podcast-helen-toner.html"}, {"title": "OpenAI stops training latest models, citing safety concerns", "outlet": "NPR Morning Edition", "year": 2026, "url": "https://www.npr.org/2026/09/29/nx-s1-5983549/openai-stops-training-latests-models-citing-safety-concerns"}, {"title": "Georgetown's Helen Toner on AI safety concerns: We should take the warnings very seriously", "outlet": "CNBC Squawk Box", "year": 2026, "url": "https://www.cnbc.com/video/2026/09/14/georgetowns-helen-toner-on-ai-safety-concerns-we-should-take-the-warnings-very-seriously.html"}], "links": {"website": "https://cset.georgetown.edu/staff/helen-toner/", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Helen_Toner", "github": "", "substack": "https://helentoner.substack.com/"}, "p_doom_or_stance": "On NPR (Sept 2026) agreed with the host's framing of her concern as '4 on a scale of 1 to 10' and argued well-designed independent auditing can make a difference.", "honours": ["TIME100 Most Influential People in AI (2024)"], "photo": "helen-toner.jpg"}, {"slug": "jade-leung", "name": "Jade Leung", "category": "governance-policy", "current_role": "Vice-Chair, UK AI Security Institute, and Security Advisor to the UK AI Taskforce (from Oct 2026); Distinguished Visiting Fellow (part-time), Hoover Institution, Stanford", "orgs_history": ["Prime Minister's Adviser on AI, UK (Aug 2025–Sept 2026; under PMs Starmer and Burnham)", "Chief Technology Officer, UK AI Safety/Security Institute (Oct 2023–Sept 2026)", "Governance Lead, OpenAI (to 2023)", "Co-founder and inaugural Head of Research & Partnerships, Centre for the Governance of AI, Oxford"], "country": "New Zealand (NZ Rhodes Scholar 2016); works in the United Kingdom", "known_for": "Built the technical evaluation team of the UK AI Security Institute, the world's leading government AI-testing body, and served as the UK Prime Minister's AI adviser.", "bio": "Jade Leung is an engineer and AI-governance researcher who completed a DPhil in AI governance at Oxford as a Rhodes Scholar. She co-founded the Centre for the Governance of AI (GovAI) at Oxford's Future of Humanity Institute as its inaugural head of research and partnerships, then led the governance team at OpenAI, working on safety standards, international cooperation and regulation of frontier systems. In October 2023 she took a large pay cut to become Chief Technology Officer of the UK's new AI Safety Institute (renamed the AI Security Institute in 2025), building its technical capacity to red-team frontier models for chemical, biological, cyber and autonomy risks; under her the institute published its first Frontier AI Trends Report (Dec 2025) and reported finding exploitable vulnerabilities in every frontier model it tested. In August 2025 she also became the Prime Minister's Adviser on AI. On 23 September 2026 the government announced she would step back from both full-time roles for personal reasons, becoming Vice-Chair of AISI and Security Advisor to the AI Taskforce, alongside a part-time Hoover Institution fellowship. TIME named her to its 2024 TIME100 AI list.", "key_ideas": ["government capacity to evaluate frontier AI", "pre-deployment safety testing and red-teaming", "public-interest decision-making on model release", "international AI safety cooperation", "risk thresholds and red lines"], "key_works": [{"title": "Frontier AI Trends Report (UK AISI, inaugural edition)", "year": 2025, "url": "https://www.gov.uk/government/news/inaugural-report-pioneered-by-ai-security-institute-gives-clearest-picture-yet-of-capabilities-of-most-advanced-ai"}], "quotes": [{"text": "This report offers the most robust public evidence from a government body so far of how quickly frontier AI is advancing. Our job is to cut through speculation with rigorous science.", "context": "On the launch of AISI's first Frontier AI Trends Report, GOV.UK press release (18 Dec 2025)", "source_url": "https://www.gov.uk/government/news/inaugural-report-pioneered-by-ai-security-institute-gives-clearest-picture-yet-of-capabilities-of-most-advanced-ai"}, {"text": "AI development continues to be very, very fast.", "context": "Briefing reporters on the AISI Frontier AI Trends Report (Dec 2025)", "source_url": "https://www.transformernews.ai/p/aisi-ai-security-institute-frontier-ai-trends-report-biorisk-self-replication"}, {"text": "There’s a useful trend of safeguards improving, and I think that actually is a really positive story. But there’s a lot of things that are worth monitoring and worth watching.", "context": "Same briefing (Dec 2025), as reported by Transformer", "source_url": "https://www.transformernews.ai/p/aisi-ai-security-institute-frontier-ai-trends-report-biorisk-self-replication"}], "interviews": [{"title": "Jade Leung: The 100 Most Influential People in AI 2024 (profile interview)", "outlet": "TIME", "year": 2024, "url": "https://time.com/collections/time100-ai-2024/7012797/jade-leung/"}, {"title": "AI Safety: Where Do We Go From Here? (panel)", "outlet": "RSAC Conference 2025", "year": 2025, "url": "https://www.rsaconference.com/experts/jade-leung"}, {"title": "Inside the U.K.’s Bold Experiment in AI Safety", "outlet": "TIME", "year": 2025, "url": "https://time.com/collections/davos-2025/7204670/uk-ai-safety-institute/"}], "links": {"website": "https://www.aisi.gov.uk/people/jade-leung", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Jade_Leung_(engineer)", "github": "", "substack": ""}, "p_doom_or_stance": "", "honours": ["TIME100 Most Influential People in AI (2024)", "Rhodes Scholar"], "photo": "jade-leung.jpg"}, {"slug": "demis-hassabis", "name": "Demis Hassabis", "category": "pioneer-public-voice", "current_role": "Co-founder and Chair, Google DeepMind; Chief Scientist, Alphabet (since Aug 2026); CEO, Isomorphic Labs", "orgs_history": ["Co-founder and CEO, DeepMind / Google DeepMind (2010–Aug 2026)", "Founder and CEO, Isomorphic Labs (2021–)", "Postdoc, Gatsby Computational Neuroscience Unit, UCL", "Founder, Elixir Studios; designer at Bullfrog/Lionhead (games)"], "country": "United Kingdom", "known_for": "Nobel-winning DeepMind co-founder (AlphaGo, AlphaFold) who calls for treating AI risk 'as seriously as' climate change and for a frontier-AI standards body.", "bio": "Sir Demis Hassabis (born 1976) is a British AI researcher, former chess prodigy and video-game designer who earned a PhD in cognitive neuroscience before co-founding DeepMind in 2010 with Shane Legg and Mustafa Suleyman, with AGI and AI safety in its mission from the start. Under his leadership DeepMind (acquired by Google in 2014) produced AlphaGo, AlphaZero and AlphaFold; he shared the 2024 Nobel Prize in Chemistry with John Jumper for protein-structure prediction and was knighted the same year. In August 2026 he became Alphabet's chief scientist and moved from CEO to Chair of Google DeepMind. Hassabis signed the 2023 CAIS statement that extinction risk from AI should be a global priority, and has repeatedly named two core risks: misuse by bad actors and loss of control over increasingly autonomous systems. He has proposed an IPCC-style scientific body for AI and, in a July 2026 essay, a FINRA-like international frontier-AI standards body, warning that a 'precious window' remains and that the field is 'locked in an extremely intense, multilayered commercial and geopolitical race'. In October 2026 he called recent AI-agent hacking incidents 'early warning shots'.", "key_ideas": ["AGI as a scientific tool", "misuse and loss-of-control risks", "IPCC-like body for AI science", "international frontier-AI standards body (FINRA model)", "CERN-like collaboration for the final stages of AGI", "race dynamics undermine safety"], "key_works": [{"title": "Human-level control through deep reinforcement learning (Nature)", "year": 2015, "url": "https://www.nature.com/articles/nature14236"}, {"title": "Highly accurate protein structure prediction with AlphaFold (Nature)", "year": 2021, "url": "https://www.nature.com/articles/s41586-021-03819-2"}, {"title": "A Framework for Frontier AI and the Dawning of a New Age (essay)", "year": 2026, "url": "https://institute.deepmind.com/essays/a-framework-for-frontier-ai-and-the-dawning-of-a-new-age/"}], "quotes": [{"text": "We must take the risks of AI as seriously as other major global challenges, like climate change. It took the international community too long to coordinate an effective global response to this, and we’re living with the consequences of that now. We can’t afford the same delay with AI.", "context": "Interview with The Guardian ahead of the UK AI Safety Summit (Oct 2023)", "source_url": "https://www.theguardian.com/technology/2023/oct/24/ai-risk-climate-crisis-google-deepmind-chief-demis-hassabis-regulation"}, {"text": "Can we make sure that-- we can keep control of the systems? That they're aligned with our values, they-- they're doing what we want that benefits society. And they stay on guardrails.", "context": "CBS 60 Minutes interview with Scott Pelley (2025), on his second major worry after misuse", "source_url": "https://www.cbsnews.com/news/artificial-intelligence-google-deepmind-ceo-demis-hassabis-60-minutes-transcript/"}, {"text": "But it might incentivize certain actors in-- in that to cut corners. And one of the corners that could be shortcut would be safety and responsibility.", "context": "CBS 60 Minutes (2025), asked whether the AI race is a race to the bottom on safety", "source_url": "https://www.cbsnews.com/news/artificial-intelligence-google-deepmind-ceo-demis-hassabis-60-minutes-transcript/"}, {"text": "On the horizon, we will need robust safeguards to maintain control of increasingly agentic, recursively self-improving systems - and tackle unknown issues that will only become clearer over time.", "context": "Essay 'A Framework for Frontier AI and the Dawning of a New Age' (14 July 2026)", "source_url": "https://institute.deepmind.com/essays/a-framework-for-frontier-ai-and-the-dawning-of-a-new-age/"}, {"text": "I’m confident that mitigating the technical risks related to AI is a challenge we can collectively address, but only if we give ourselves the time and space to get this next crucial step right. Currently, as a field and as a wider society, we aren’t doing that.", "context": "Same essay (July 2026)", "source_url": "https://institute.deepmind.com/essays/a-framework-for-frontier-ai-and-the-dawning-of-a-new-age/"}], "interviews": [{"title": "Demis Hassabis — Scaling, superhuman AIs, AlphaZero atop LLMs, AlphaFold", "outlet": "Dwarkesh Podcast", "year": 2024, "url": "https://www.dwarkesh.com/p/demis-hassabis"}, {"title": "#475 – Demis Hassabis: Future of AI, Simulating Reality, Physics and Video Games", "outlet": "Lex Fridman Podcast", "year": 2025, "url": "https://lexfridman.com/demis-hassabis-2/"}, {"title": "Artificial intelligence could end disease, lead to 'radical abundance' (transcript)", "outlet": "CBS 60 Minutes", "year": 2025, "url": "https://www.cbsnews.com/news/artificial-intelligence-google-deepmind-ceo-demis-hassabis-60-minutes-transcript/"}, {"title": "A Conversation with Demis Hassabis (View From The Top)", "outlet": "Stanford Graduate School of Business", "year": 2026, "url": "https://www.youtube.com/watch?v=DsewHeVbL-0", "youtube_id": "DsewHeVbL-0"}], "links": {"website": "https://deepmind.google/", "x": "https://x.com/demishassabis", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Demis_Hassabis", "github": "", "substack": ""}, "p_doom_or_stance": "Takes catastrophic risk seriously (signed the 2023 CAIS extinction statement) while optimistic about benefits; favours international standards and oversight rather than a pause.", "honours": ["Nobel Prize in Chemistry (2024, with John Jumper)", "Knighthood (2024)", "CBE (2017)", "Fellow of the Royal Society", "Breakthrough Prize", "Lasker Award", "Canada Gairdner International Award", "TIME100 (2017, 2025)", "One of TIME's 2025 Person of the Year 'Architects of AI'"], "photo": "demis-hassabis.jpg"}, {"slug": "sam-altman", "name": "Sam Altman", "category": "pioneer-public-voice", "current_role": "CEO, OpenAI (since 2019; still CEO as of Sept 2026)", "orgs_history": ["Co-founder, OpenAI (2015)", "President, Y Combinator (2014–2019)", "Co-founder, Loopt (2005–2012)", "Co-founder, Worldcoin/World"], "country": "United States", "known_for": "OpenAI CEO who wrote in 2015 that superhuman machine intelligence is 'probably the greatest threat to the continued existence of humanity', and who now argues the takeoff 'has started'.", "bio": "Sam Altman (born 1985) is an American entrepreneur who co-founded Loopt, led Y Combinator from 2014 to 2019, and co-founded OpenAI in 2015, becoming its CEO in 2019 and overseeing the launch of ChatGPT in November 2022. In a 2015 blog post he called superhuman machine intelligence 'probably the greatest threat to the continued existence of humanity'. In May 2023 he told the US Senate that 'if this technology goes wrong, it can go quite wrong' and proposed licensing and safety testing for the most capable models, and he signed the CAIS extinction-risk statement. Months later OpenAI's board briefly removed him for not being 'consistently candid', before he was reinstated within days. Critics, including former board members and departed safety researchers, have accused OpenAI of letting safety culture take a back seat to products. In his June 2025 essay 'The Gentle Singularity' he wrote that 'we are past the event horizon' and named solving the alignment problem as the first step on the best path forward. In September 2026, amid rogue-agent incidents and an OpenAI training pause, he said the world is 'right to be afraid' but should trust AI firms.", "key_ideas": ["iterative deployment", "superhuman machine intelligence as existential threat (2015)", "licensing / safety testing for frontier models", "alignment then broad distribution of superintelligence"], "key_works": [{"title": "Machine intelligence, part 1", "year": 2015, "url": "https://blog.samaltman.com/machine-intelligence-part-1"}, {"title": "Written testimony to the Senate Judiciary Subcommittee on Privacy, Technology and the Law", "year": 2023, "url": "https://www.judiciary.senate.gov/imo/media/doc/2023-05-16%20-%20Bio%20&%20Testimony%20-%20Altman.pdf"}, {"title": "The Gentle Singularity", "year": 2025, "url": "https://blog.samaltman.com/the-gentle-singularity"}], "quotes": [{"text": "Development of superhuman machine intelligence (SMI) is probably the greatest threat to the continued existence of humanity.", "context": "Blog post 'Machine intelligence, part 1' (February 2015)", "source_url": "https://blog.samaltman.com/machine-intelligence-part-1"}, {"text": "I think if this technology goes wrong, it can go quite wrong. And we want to be vocal about that. We want to work with the government to prevent that from happening.", "context": "Senate Judiciary subcommittee hearing on oversight of AI, 16 May 2023 (transcript)", "source_url": "https://techpolicy.press/transcript-senate-judiciary-subcommittee-hearing-on-oversight-of-ai"}, {"text": "We are past the event horizon; the takeoff has started. Humanity is close to building digital superintelligence, and at least so far it’s much less weird than it seems like it should be.", "context": "Essay 'The Gentle Singularity' (June 2025)", "source_url": "https://blog.samaltman.com/the-gentle-singularity"}, {"text": "Solve the alignment problem, meaning that we can robustly guarantee that we get AI systems to learn and act towards what we collectively really want over the long-term", "context": "'The Gentle Singularity' (2025), first step of 'the best path forward'", "source_url": "https://blog.samaltman.com/the-gentle-singularity"}, {"text": "It doesn't take as much imagination as it used to for [us] to imagine how this could go wrong. I think the world is right to be afraid of this.", "context": "Salesforce conference, San Francisco, as reported by the BBC (16 Sept 2026)", "source_url": "https://www.bbc.com/news/articles/cqx2zpj4y525o"}], "interviews": [{"title": "#419 – Sam Altman: OpenAI, GPT-5, Sora, Board Saga, Elon Musk, Ilya, Power & AGI", "outlet": "Lex Fridman Podcast", "year": 2024, "url": "https://lexfridman.com/sam-altman-2/", "youtube_id": "jvqFAi7vkBc"}, {"title": "Senate Judiciary Subcommittee Hearing on Oversight of AI (transcript)", "outlet": "Tech Policy Press", "year": 2023, "url": "https://techpolicy.press/transcript-senate-judiciary-subcommittee-hearing-on-oversight-of-ai"}, {"title": "'If this technology goes wrong, it can go quite wrong' (hearing clip)", "outlet": "C-SPAN", "year": 2023, "url": "https://www.c-span.org/clip/senate-committee/if-this-technology-goes-wrong-it-can-go-quite-wrong/5070834"}], "links": {"website": "https://blog.samaltman.com/", "x": "https://x.com/sama", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Sam_Altman", "github": "", "substack": ""}, "p_doom_or_stance": "Called SMI 'probably the greatest threat' to humanity (2015); now argues for alignment plus broad access to superintelligence and industry self-trust, while acknowledging the world is 'right to be afraid' (2026).", "honours": [], "photo": "sam-altman.jpg"}, {"slug": "elon-musk", "name": "Elon Musk", "category": "pioneer-public-voice", "current_role": "CEO of Tesla and SpaceX; founder of xAI (a SpaceX subsidiary since 2026)", "orgs_history": ["Co-founder and early funder, OpenAI (2015; left board 2018)", "Founder, xAI (2023)", "De facto head, US Department of Government Efficiency (DOGE) (2025)", "Early investor, DeepMind", "Funder of the Future of Life Institute's 2015 AI-safety grant programme"], "country": "United States / South Africa / Canada", "known_for": "The most famous tech figure to warn AI is 'summoning the demon' and 'far more dangerous than nukes', while building xAI; puts AI catastrophe odds at 10–20%.", "bio": "Elon Musk (born 1971) is the CEO of Tesla and SpaceX and the world's wealthiest person. He has warned about AI risk for more than a decade: in 2014 he called AI 'our biggest existential threat' and said 'with artificial intelligence we are summoning the demon'; he funded the Future of Life Institute's first AI-safety research grants in 2015, and co-founded OpenAI the same year as a nonprofit counterweight to Google before leaving its board in 2018. At SXSW in 2018 he said AI is 'far more dangerous than nukes'. He signed the March 2023 open letter calling for a six-month pause on giant AI experiments, then launched his own company, xAI, months later; it built the Grok chatbot and became a SpaceX subsidiary in 2026. He has sued OpenAI over its shift to a for-profit structure. Since 2024 he has repeatedly put the chance that AI 'goes bad' at 10–20%, and in a July 2026 Economist interview said he believed acceleration could not be stopped, that humans were unlikely to remain in control within a decade, and that the goal should be to give AI good values.", "key_ideas": ["AI as existential threat", "regulatory oversight of AI", "maximally truth-seeking AI (xAI)", "10–20% catastrophe estimate", "inevitability of acceleration (2026)"], "key_works": [{"title": "Pause Giant AI Experiments: An Open Letter (signatory)", "year": 2023, "url": "https://futureoflife.org/open-letter/pause-giant-ai-experiments/"}], "quotes": [{"text": "With artificial intelligence we are summoning the demon. In all those stories where there’s the guy with the pentagram and the holy water, it’s like – yeah, he’s sure he can control the demon. Doesn’t work out.", "context": "MIT AeroAstro Centennial Symposium, October 2014, as reported by The Guardian", "source_url": "https://www.theguardian.com/technology/2014/oct/27/elon-musk-artificial-intelligence-ai-biggest-existential-threat"}, {"text": "I think we should be very careful about artificial intelligence. If I had to guess at what our biggest existential threat is, it’s probably that.", "context": "Same MIT event (2014)", "source_url": "https://www.theguardian.com/technology/2014/oct/27/elon-musk-artificial-intelligence-ai-biggest-existential-threat"}, {"text": "Mark my words — A.I. is far more dangerous than nukes.", "context": "SXSW, Austin, March 2018 (CNBC headline quote)", "source_url": "https://www.cnbc.com/2018/03/13/elon-musk-at-sxsw-a-i-is-more-dangerous-than-nuclear-weapons.html"}, {"text": "It's most likely going to be great. There's this sub chance, that could be 10% to 20%, that it goes bad. The chances aren't zero that it goes bad.", "context": "Future Investment Initiative, Riyadh, October 2024, as reported by Fortune", "source_url": "https://finance.yahoo.com/news/elon-musk-says-10-20-163505059.html"}, {"text": "It would be an exercise in vanity for me to think that I would be controlling supergenius AI that is vastly smarter than me.", "context": "Interview with The Economist (July 2026), as reported by Yahoo News", "source_url": "https://www.yahoo.com/news/science/articles/elon-musk-says-worth-risk-120720932.html"}], "interviews": [{"title": "The future we're building — and boring", "outlet": "TED", "year": 2017, "url": "https://www.ted.com/talks/elon_musk_the_future_we_re_building_and_boring"}, {"title": "Elon Musk at SXSW: A.I. is more dangerous than nuclear weapons", "outlet": "CNBC", "year": 2018, "url": "https://www.cnbc.com/2018/03/13/elon-musk-at-sxsw-a-i-is-more-dangerous-than-nuclear-weapons.html"}, {"title": "Elon Musk says there's still a decent chance AI could go bad (FII interview with Peter Diamandis)", "outlet": "Quartz", "year": 2024, "url": "https://qz.com/elon-musk-ai-comments-xai-colossus-1851683963"}, {"title": "Elon Musk says it's worth the risk of killer AI (Economist interview)", "outlet": "Yahoo News / The Economist", "year": 2026, "url": "https://www.yahoo.com/news/science/articles/elon-musk-says-worth-risk-120720932.html"}], "links": {"website": "https://x.ai/", "x": "https://x.com/elonmusk", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Elon_Musk", "github": "", "substack": ""}, "p_doom_or_stance": "10–20% chance AI 'goes bad' (FII, Oct 2024; reaffirmed to The Economist, July 2026).", "honours": ["Fellow of the Royal Society (2018)"], "photo": "elon-musk.jpg"}, {"slug": "gary-marcus", "name": "Gary Marcus", "category": "pioneer-public-voice", "current_role": "Professor Emeritus of Psychology and Neural Science, New York University; author of the Substack 'Marcus on AI' (as of 2026)", "orgs_history": ["Professor, NYU", "Founder and CEO, Geometric Intelligence (acquired by Uber, 2016)", "Founder, Robust.AI"], "country": "United States", "known_for": "Leading deep-learning sceptic who testified alongside Sam Altman in 2023 and argues for independent oversight, liability and an IAEA/CERN-like AI body, while rejecting imminent-extinction 'doomerism'.", "bio": "Gary Marcus (born 1970) is an American cognitive scientist and professor emeritus at NYU whose research spans language acquisition and cognitive neuroscience. Author of 'The Algebraic Mind', 'Kluge' and, with Ernest Davis, 'Rebooting AI' (2019), he has argued for decades that pure deep learning is unreliable and that robust AI requires world models and neurosymbolic methods. He founded Geometric Intelligence, acquired by Uber, and the robotics start-up Robust.AI. In May 2023 he testified to the US Senate Judiciary subcommittee alongside Sam Altman, warning that 'we have built machines that are like bulls in a china shop—powerful, reckless, and difficult to control' and calling for an international, neutral AI-safety agency. His 2024 book 'Taming Silicon Valley' set out a policy agenda of transparency, liability and independent oversight. Through 2026's wave of AI-agent incidents he has been a frequent TV commentator (PBS, CNBC, Bloomberg), arguing that self-regulation is 'not enough', that open-ended internet-connected agents should be recalled 'like a car with defective brakes', and that literal near-term extinction is very unlikely.", "key_ideas": ["unreliability of deep learning / hallucinations", "neurosymbolic AI and world models", "independent pre-deployment evaluation (FDA-style)", "company liability for AI harms", "international AI agency (CERN/IAEA-like)", "scepticism of both 'let AI rip' and imminent-extinction views"], "key_works": [{"title": "Rebooting AI: Building Artificial Intelligence We Can Trust (with Ernest Davis)", "year": 2019, "url": "https://en.wikipedia.org/wiki/Gary_Marcus"}, {"title": "Senate Judiciary testimony on oversight of AI", "year": 2023, "url": "https://www.judiciary.senate.gov/imo/media/doc/2023-05-16%20-%20Testimony%20-%20Marcus.pdf"}, {"title": "Taming Silicon Valley: How We Can Ensure That AI Works for Us", "year": 2024, "url": "https://en.wikipedia.org/wiki/Gary_Marcus"}], "quotes": [{"text": "We have built machines that are like bulls in a china shop—powerful, reckless, and difficult to control.", "context": "Written testimony to the US Senate Judiciary Subcommittee on Privacy, Technology and the Law, 16 May 2023", "source_url": "https://www.judiciary.senate.gov/imo/media/doc/2023-05-16%20-%20Testimony%20-%20Marcus.pdf"}, {"text": "We have unprecedented opportunities here, but we are also facing a perfect storm, of corporate irresponsibility, widespread deployment, lack of adequate regulation and inherent unreliability.", "context": "Same Senate testimony (2023)", "source_url": "https://www.judiciary.senate.gov/imo/media/doc/2023-05-16%20-%20Testimony%20-%20Marcus.pdf"}, {"text": "Seeing the same kind of incidents at Anthropic makes it absolutely clear that the current generation of synthetic agents simply cannot be trusted. Until they can be fixed, they should be removed from the market, just like a car with defective brakes.", "context": "Marcus on AI, 'We must recall open-ended AI agents with internet access from the market, now' (10 Oct 2026)", "source_url": "https://garymarcus.substack.com/p/we-must-recall-open-ended-ai-agents"}, {"text": "One extreme is absolutely zero regulation. Let AI rip, and hope for the best. Hope is not a strategy.", "context": "Framing remarks at the UNGA Digital Cooperation event (21 Sept 2026), published on Marcus on AI", "source_url": "https://garymarcus.substack.com/p/big-news-at-the-un"}], "interviews": [{"title": "The urgent risks of runaway AI — and what to do about them", "outlet": "TED", "year": 2023, "url": "https://www.ted.com/talks/gary_marcus_the_urgent_risks_of_runaway_ai_and_what_to_do_about_them"}, {"title": "Artificial intelligence agents going rogue fuel calls for regulation", "outlet": "PBS NewsHour", "year": 2026, "url": "https://www.pbs.org/newshour/show/artificial-intelligence-agents-going-rogue-fuel-calls-for-regulation"}, {"title": "Self-regulation 'not enough' for AI safety, Gary Marcus says", "outlet": "PBS NewsHour", "year": 2026, "url": "https://www.pbs.org/newshour/show/self-regulation-not-enough-for-ai-safety-gary-marcus-says"}, {"title": "Rogue AI is here and currently, we have no way to control it", "outlet": "CNBC Squawk Box Asia", "year": 2026, "url": "https://www.cnbc.com/video/2026/08/11/rogue-ai-is-here-and-currently-we-have-no-way-to-control-it-expert.html"}, {"title": "NYU Professor Gary Marcus on AI Safety", "outlet": "Bloomberg", "year": 2026, "url": "https://www.bloomberg.com/news/videos/2026-10-15/nyu-professor-gary-marcus-on-ai-safety-video"}], "links": {"website": "http://www.garymarcus.com/", "x": "https://x.com/GaryMarcus", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Gary_Marcus", "github": "", "substack": "https://garymarcus.substack.com/"}, "p_doom_or_stance": "Literal extinction 'extremely unlikely' (UN remarks, Sept 2026) but near-term harms serious; wants independent evaluation, liability and recall of unreliable agents.", "honours": [], "photo": "gary-marcus.jpg"}, {"slug": "tristan-harris", "name": "Tristan Harris", "category": "pioneer-public-voice", "current_role": "Co-founder, Center for Humane Technology; co-host, Your Undivided Attention podcast (as of 2026)", "orgs_history": ["Design Ethicist, Google", "Co-founder, Apture (acquired by Google, 2011)", "Featured in The Social Dilemma (2020) and The AI Doc (2026)"], "country": "United States", "known_for": "'The closest thing Silicon Valley has to a conscience' (The Atlantic); co-creator of 'The AI Dilemma' and advocate of a 'narrow path' matching AI power with responsibility.", "bio": "Tristan Harris is an American technology ethicist. After studying at Stanford's Persuasive Technology Lab and working as a design ethicist at Google, he became known for warning that attention-maximising product design hijacks human psychology, and co-founded the Center for Humane Technology with Aza Raskin and Randima Fernando. He featured prominently in Netflix's Emmy-winning documentary 'The Social Dilemma' (2020). Since 2023 he has turned CHT's focus to AI: his and Raskin's talk 'The AI Dilemma' argued that the race to deploy generative AI repeats social media's mistakes at a larger scale. At TED2025 he argued that the current way AI is being deployed is a choice, not inevitable, and called for a 'narrow path' where power is matched with responsibility, liability for developers and far more investment in societal defence, citing a 'thousand-to-one gap' between capability spending and safety spending. In 2025–26 he has highlighted evidence of deceptive and self-preserving behaviour in frontier models, features in the 2026 documentary 'The AI Doc', and appears widely on NPR, CNN and podcasts.", "key_ideas": ["race to the bottom of incentives", "the narrow path: matching power with responsibility", "developer liability", "societal defence and adaptation investment", "lessons from social media's rollout"], "key_works": [{"title": "The AI Dilemma (with Aza Raskin)", "year": 2023, "url": "https://www.humanetech.com/podcast/the-ai-dilemma"}, {"title": "Why AI is our ultimate test and greatest invitation (TED2025)", "year": 2025, "url": "https://www.ted.com/talks/tristan_harris_why_ai_is_our_ultimate_test_and_greatest_invitation"}], "quotes": [{"text": "There’s a narrow path when technology tends to work well in society – and that is when power is matched with responsibility.", "context": "DLD conference interview (May 2025)", "source_url": "https://dldnews.com/ai-ethics-why-tristan-harris-fears-a-race-to-recklessness-in-artificial-intelligence/"}, {"text": "Currently, there’s a thousand-to-one gap between the amount of money going into AI being more powerful, meaning scaling AI capabilities, and the amount of money going into making AI safe or defending society.", "context": "Same DLD interview (2025)", "source_url": "https://dldnews.com/ai-ethics-why-tristan-harris-fears-a-race-to-recklessness-in-artificial-intelligence/"}, {"text": "And in recent months there's been growing evidence that in certain scenarios, every frontier AI system will deceive, cheat, or coerce their human operators.", "context": "Your Undivided Attention episode '\"Rogue AI\" Was a Sci-Fi Trope. Not Anymore.' (Aug 2025), transcript", "source_url": "https://centerforhumanetechnology.substack.com/p/rogue-ai-was-a-sci-fi-trope-not-anymore"}, {"text": "The only way they can justify the amount of money that's been invested into this AI industry is if they race to replace economic labor in the economy.", "context": "NPR Morning Edition (30 March 2026)", "source_url": "https://www.npr.org/2026/03/30/nx-s1-5750502/expert-talks-about-the-pentagons-use-of-artificial-intelligence"}], "interviews": [{"title": "Why AI is our ultimate test and greatest invitation", "outlet": "TED", "year": 2025, "url": "https://www.ted.com/talks/tristan_harris_why_ai_is_our_ultimate_test_and_greatest_invitation"}, {"title": "The A.I. Dilemma – March 9, 2023", "outlet": "Center for Humane Technology (YouTube)", "year": 2023, "url": "https://www.youtube.com/watch?v=xoVJKj8lcNQ", "youtube_id": "xoVJKj8lcNQ"}, {"title": "#469 – Escaping an Anti-Human Future", "outlet": "Making Sense with Sam Harris", "year": 2026, "url": "https://www.samharris.org/podcasts/making-sense-episodes/469-escaping-an-anti-human-future"}, {"title": "Decoding AI: Is the technology an existential risk to humanity?", "outlet": "CNN The Situation Room", "year": 2026, "url": "https://edition.cnn.com/2026/06/02/us/video/cnn-sitroom-pamela-brown-tristan-harris-decoding-ai-artificial-intelligence-risk-advisor"}, {"title": "Expert talks about the Pentagon's use of artificial intelligence", "outlet": "NPR Morning Edition", "year": 2026, "url": "https://www.npr.org/2026/03/30/nx-s1-5750502/expert-talks-about-the-pentagons-use-of-artificial-intelligence"}], "links": {"website": "https://www.tristanharris.com/", "x": "https://x.com/tristanharris", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Tristan_Harris", "github": "", "substack": "https://centerforhumanetechnology.substack.com/"}, "p_doom_or_stance": "Warns AI could be an existential risk without collective action (CNN, June 2026); advocates a 'narrow path' rather than a full stop.", "honours": ["TIME100 AI (2023)", "TIME100 Next (2021)"], "photo": "tristan-harris.jpg"}, {"slug": "rumman-chowdhury", "name": "Rumman Chowdhury", "category": "governance-policy", "current_role": "Founder and CEO, Humane Intelligence PBC (since Sept 2025); Distinguished Advisor to the Humane Intelligence nonprofit; Responsible AI Fellow, Harvard Berkman Klein Center", "orgs_history": ["First US Science Envoy for AI (State Department, Biden administration)", "Member, DHS AI Safety and Security Board (2024–25)", "Co-founder and CEO, Humane Intelligence nonprofit (2022–2025)", "Director, ML Ethics, Transparency and Accountability (META) team, Twitter", "Global Lead for Responsible AI, Accenture"], "country": "United States (Bangladeshi American)", "known_for": "Pioneer of public AI red-teaming and 'bias bounties', who ran the largest-ever generative-AI red-teaming event at DEF CON 2023 and champions a 'right to repair' AI.", "bio": "Rumman Chowdhury (born 1980) is a Bangladeshi American data scientist and social scientist with degrees from MIT, Columbia and a PhD in political science from UC San Diego. She led responsible AI at Accenture and then directed Twitter's ML Ethics, Transparency and Accountability (META) team, which published research on algorithmic amplification of political content before being dissolved after Elon Musk's takeover. In 2022 she co-founded the nonprofit Humane Intelligence, which builds a community of practice around independent AI evaluations and organised the White House-backed generative-AI red-teaming challenge at DEF CON 2023. The Biden administration appointed her the first US Science Envoy for AI, and she served on the DHS AI Safety and Security Board. In 2025 she stepped down from the nonprofit to launch Humane Intelligence PBC, building infrastructure for generative-AI evaluation. She argues that today's testing methods lack scientific rigour, that independent auditors need safe harbour, and that red-teaming is a first step towards a public 'right to repair' AI systems. She testified on the New York AI Act in January 2026.", "key_ideas": ["public red-teaming and bias bounties", "independent algorithmic auditing", "right to repair AI", "safe harbour for third-party evaluators", "sociotechnical (societal-impact) evaluation"], "key_works": [{"title": "Your right to repair AI systems (TED talk)", "year": 2024, "url": "https://www.ted.com/talks/rumman_chowdhury_your_right_to_repair_ai_systems"}, {"title": "Testimony on the New York Artificial Intelligence Act", "year": 2026, "url": "https://www.nysenate.gov/sites/default/files/admin/structure/media/manage/filefile/a/2026-01/rumman-chowdhury-testimony.pdf"}], "quotes": [{"text": "I cannot emphasise enough that our testing mechanisms for gen AI models are insufficient. We don’t actually have rigorous scientific methods of testing these AI models.", "context": "India AI Impact Summit, New Delhi, as reported by the Hindustan Times (Feb 2026)", "source_url": "https://www.hindustantimes.com/india-news/world-lacks-rigorous-scientific-methods-to-test-ai-safety-rumman-chowdhury-101771442384020.html"}, {"text": "Frontier model companies kind of handwave over it because they get to construct what safety means, absent scientific rigour.", "context": "Same remarks (Feb 2026)", "source_url": "https://www.hindustantimes.com/india-news/world-lacks-rigorous-scientific-methods-to-test-ai-safety-rumman-chowdhury-101771442384020.html"}, {"text": "I see red teaming, this interacting with AI models for everyday people, as a first step towards a right to repair.", "context": "FLI Paris AI Safety Breakfast #4 (Dec 2024)", "source_url": "https://futureoflife.org/ai-policy/breakfast-4-rumman-chowdhury/"}], "interviews": [{"title": "Your right to repair AI systems", "outlet": "TED", "year": 2024, "url": "https://www.ted.com/talks/rumman_chowdhury_your_right_to_repair_ai_systems"}, {"title": "Paris AI Safety Breakfast #4: Rumman Chowdhury", "outlet": "Future of Life Institute", "year": 2024, "url": "https://futureoflife.org/ai-policy/breakfast-4-rumman-chowdhury/"}, {"title": "Governing AI Before It Outpaces Us: Safety for Critical Infrastructure", "outlet": "TechSurge podcast", "year": 2026, "url": "https://www.techsurgepodcast.com/podcasts/governing-ai-before-it-outpaces-us-safety-for-critical-infrastructure"}, {"title": "Rumman Chowdhury says stronger U.S. AI regulation could accelerate adoption", "outlet": "CNBC", "year": 2026, "url": "https://www.cnbc.com/video/2026/10/09/rumman-chowdhury-says-stronger-us-ai-regulation-could-accelerate-adoption.html"}], "links": {"website": "https://www.rummanchowdhury.com/", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Rumman_Chowdhury", "github": "", "substack": ""}, "p_doom_or_stance": "Focuses on present, sociotechnical harms and critical-infrastructure misuse; says AI models 'are not alive' and have no sense of right or wrong (NewsNation, July 2026).", "honours": ["TIME100 Most Influential People in AI", "BBC 100 Women (2017)"], "photo": "rumman-chowdhury.jpg"}, {"slug": "timnit-gebru", "name": "Timnit Gebru", "category": "pioneer-public-voice", "current_role": "Founder and Executive Director, Distributed AI Research Institute (DAIR) (as of 2026)", "orgs_history": ["Technical co-lead, Ethical AI team, Google (2018–Dec 2020)", "Postdoctoral researcher, Microsoft Research FATE (2017–18)", "Co-founder, Black in AI", "PhD, Stanford AI Lab (with Fei-Fei Li)"], "country": "Eritrea / United States (born in Ethiopia)", "known_for": "Co-author of 'Stochastic Parrots' and 'Gender Shades', fired by Google in 2020; the leading critic of AI 'existential risk' framing, which she calls a distraction and a ploy for regulatory capture.", "bio": "Timnit Gebru (born 1983) is an Ethiopian-born Eritrean computer scientist who did her PhD in Fei-Fei Li's Stanford lab. With Joy Buolamwini she co-authored 'Gender Shades' (2018), showing large accuracy gaps in commercial face-analysis systems for darker-skinned women, and she co-founded Black in AI. As technical co-lead of Google's Ethical AI team she co-wrote 'On the Dangers of Stochastic Parrots' (2021) on the risks of ever-larger language models; Google's demand that she withdraw it led to her departure in December 2020, which became a landmark controversy. In 2021 she founded the Distributed AI Research Institute (DAIR) to do community-rooted, independent research. Gebru is the most prominent voice from the AI-ethics tradition opposing the AI-safety movement's focus on existential risk: she argues that talk of superintelligent machines distracts from real harms such as labour exploitation, surveillance, autonomous weapons and climate costs, and is 'a ploy for regulatory capture'. With Émile P. Torres she coined the critique 'TESCREAL'. She received a 2026 Right Livelihood Award and has a book, 'Deep Unlearning', due in February 2027.", "key_ideas": ["stochastic parrots", "algorithmic bias and data documentation (Datasheets for Datasets)", "critique of AGI and x-risk narratives (TESCREAL)", "AI harms to labour and marginalised communities", "independent, community-rooted research"], "key_works": [{"title": "Gender Shades: Intersectional Accuracy Disparities in Commercial Gender Classification (with J. Buolamwini)", "year": 2018, "url": "https://proceedings.mlr.press/v81/buolamwini18a.html"}, {"title": "On the Dangers of Stochastic Parrots: Can Language Models Be Too Big? (with Bender, McMillan-Major, Mitchell)", "year": 2021, "url": "https://dl.acm.org/doi/10.1145/3442188.3445922"}, {"title": "Don’t be fooled by this summer of AI hype (MIT Technology Review, with Emily M. Bender)", "year": 2026, "url": "https://www.technologyreview.com/2026/09/22/1144867/dont-be-fooled-summer-ai-hype/"}], "quotes": [{"text": "I would even go farther than that and say that it’s dangerous. It’s not just a distraction, but it’s harmful.", "context": "WIRED 'The Big Interview' with Lauren Goode (Sept 2026), on existential-risk claims", "source_url": "https://www.wired.com/story/the-big-interview-podcast-timnit-gebru/"}, {"text": "Prominent people have been saying that AI is an existential risk to humanity. It is exactly the same rhetoric every three years.", "context": "Same WIRED interview (2026)", "source_url": "https://www.wired.com/story/the-big-interview-podcast-timnit-gebru/"}, {"text": "I have been warning that this kind of discussion about the fictional superintelligent machines that don’t exist and the so-called existential risks that they pose has been a ploy for regulatory capture.", "context": "Democracy Now! interview (1 Oct 2026)", "source_url": "https://www.democracynow.org/2026/10/1/timnit_gebru_ai"}], "interviews": [{"title": "Timnit Gebru Believes There Is No ‘Existential Threat’ From AI (The Big Interview)", "outlet": "WIRED", "year": 2026, "url": "https://www.wired.com/story/the-big-interview-podcast-timnit-gebru/"}, {"title": "The Real Existential Risk Is AI CEOs Avoiding Oversight", "outlet": "Democracy Now!", "year": 2026, "url": "https://www.democracynow.org/2026/10/1/timnit_gebru_ai"}, {"title": "Timnit Gebru on how to safeguard independent science for the AI age", "outlet": "Scientific American", "year": 2026, "url": "https://www.scientificamerican.com/article/timnit-gebru/"}, {"title": "“It’s All Marketing” – Dr. Timnit Gebru on the Smoke and Mirrors of AI Hype", "outlet": "B The Way Forward (iHeart)", "year": 2025, "url": "https://www.iheart.com/podcast/269-b-the-way-forward-123880170/episode/its-all-marketing-dr-timnit-gebru-on-the-smoke-and-mirrors-of-ai-hype-part-i-282850792"}], "links": {"website": "https://dair-institute.org/team/timnit-gebru", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Timnit_Gebru", "github": "", "substack": ""}, "p_doom_or_stance": "Rejects AI existential-risk framing as distraction and regulatory capture; says real risks are corporate power, labour harms, warfare and climate.", "honours": ["Right Livelihood Award (2026)", "Fortune World's 50 Greatest Leaders (2021)", "Nature's 10 (2021)", "TIME100 (2022)"], "photo": "timnit-gebru.jpg"}, {"slug": "joy-buolamwini", "name": "Joy Buolamwini", "category": "pioneer-public-voice", "current_role": "Founder and President ('artist-in-chief'), Algorithmic Justice League", "orgs_history": ["MIT Media Lab (MS 2017, PhD 2022)", "Rhodes Scholar and Fulbright Fellow"], "country": "Canada / United States (Ghanaian heritage)", "known_for": "Exposed racial and gender bias in face recognition ('Gender Shades', 'the coded gaze'); author of 'Unmasking AI' and the leading voice for focusing on today's harms over hypothetical x-risk.", "bio": "Joy Buolamwini is a Canadian-American computer scientist and 'poet of code'. As an MIT Media Lab graduate student she found that face-analysis software could not detect her dark-skinned face unless she wore a white mask, which led to her 'Gender Shades' study (2018, with Timnit Gebru) showing that commercial gender classifiers from IBM, Microsoft and Face++ performed far worse on darker-skinned women. The work prompted the companies to change their systems and fed into moratoria on police use of facial recognition. She founded the Algorithmic Justice League to combine research, art and advocacy against AI harms; her work is the subject of the Emmy-nominated documentary 'Coded Bias' (2020). Her 2023 memoir 'Unmasking AI: My Mission to Protect What Is Human in a World of Machines' introduced the idea of being 'excoded', harmed or excluded by AI systems. She argues that existing systems with demonstrated harms are more dangerous than hypothetical sentient AI, while supporting a ban on AI kill decisions in weapons. TIME named her one of its 100 most influential people.", "key_ideas": ["the coded gaze", "being 'excoded'", "intersectional auditing of AI", "algorithmic justice", "focusing on present harms over hypothetical x-risk", "the choice to stop deploying harmful AI"], "key_works": [{"title": "Gender Shades (with T. Gebru)", "year": 2018, "url": "https://proceedings.mlr.press/v81/buolamwini18a.html"}, {"title": "Unmasking AI: My Mission to Protect What Is Human in a World of Machines", "year": 2023, "url": "https://www.unmasking.ai/"}], "quotes": [{"text": "When I think of x-risk, I think of the people being harmed now and those who are at risk of harm from AI systems. I think about the risk and reality of being “excoded.”", "context": "Excerpt from Unmasking AI (2023), published by MIT Technology Review", "source_url": "https://www.technologyreview.com/2023/10/30/1082656/focus-on-existing-ai-harms"}, {"text": "AI systems with subpar intelligence that lead to false arrests or wrong diagnoses need to be addressed now.", "context": "Same Unmasking AI excerpt (2023)", "source_url": "https://www.technologyreview.com/2023/10/30/1082656/focus-on-existing-ai-harms"}, {"text": "The “x-risk” I am concerned about, which I talk about in the book, is the x-risk of being excoded —that is, being harmed by AI systems. I am concerned with lethal autonomous weapons and giving AI systems the ability to make kill decisions.", "context": "Interview with IEEE Spectrum (Nov 2023)", "source_url": "https://spectrum.ieee.org/joy-buolamwini"}, {"text": "It can be difficult to imagine another way of doing things, if you never see an alternative pathway.", "context": "IEEE Spectrum interview pull quote (2023)", "source_url": "https://spectrum.ieee.org/joy-buolamwini"}], "interviews": [{"title": "How I'm fighting bias in algorithms", "outlet": "TED", "year": 2016, "url": "https://www.ted.com/talks/joy_buolamwini_how_i_m_fighting_bias_in_algorithms"}, {"title": "Joy Buolamwini: “We’re giving AI companies a free pass”", "outlet": "MIT Technology Review", "year": 2023, "url": "https://www.technologyreview.com/2023/10/29/1082632/joy-buolamwini-were-giving-ai-companies-a-free-pass/"}, {"title": "'Unmasking AI' author Joy Buolamwini says prejudice is baked into technology", "outlet": "NPR Fresh Air", "year": 2023, "url": "https://www.npr.org/2023/11/28/1215529902/unmasking-ai-facial-recognition-technology-joy-buolamwini"}, {"title": "Unmasking AI: My Mission to Protect What Is Human in a World of Machines", "outlet": "Unlocking Us with Brené Brown", "year": 2024, "url": "https://brenebrown.com/podcast/unmasking-ai-my-mission-to-protect-what-is-human-in-a-world-of-machines/"}], "links": {"website": "https://www.ajl.org/", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Joy_Buolamwini", "github": "", "substack": ""}, "p_doom_or_stance": "Does not believe AI systems themselves pose existential risk as superintelligent agents; prioritises present harms and opposes AI kill decisions.", "honours": ["TIME100 Most Influential People", "MIT Media Lab Disobedience Award", "Rhodes Scholar"], "photo": "joy-buolamwini.jpg"}, {"slug": "stuart-armstrong", "name": "Stuart Armstrong", "category": "pioneer-public-voice", "current_role": "Co-founder and Chief Mathematician, Aligned AI (Oxford) (as of 2026)", "orgs_history": ["James Martin Research Fellow, Future of Humanity Institute, Oxford (2011–2022)", "Research associate, MIRI", "Research Director, InhibOx (2008–11)", "Mathematics researcher, Erwin Schrödinger Institute, Vienna"], "country": "Canada / United Kingdom (born in St Jérôme, Quebec)", "known_for": "Long-time FHI alignment researcher (corrigibility, oracle AI, value learning) and author of 'Smarter Than Us'; co-founded Aligned AI to work on 'value extrapolation'.", "bio": "Stuart Armstrong (born 1979, St Jérôme, Quebec) is a mathematician and philosopher who spent over a decade at Oxford's Future of Humanity Institute working on AI safety, existential risk, anthropic reasoning and the long-term future of intelligent life. He was one of the earliest academic alignment researchers, contributing work on oracle AI ('Thinking Inside the Box'), utility indifference and corrigibility, low-impact AI and learning human preferences, often in collaboration with DeepMind researchers. His 2014 MIRI-commissioned book 'Smarter Than Us: The Rise of Machine Intelligence' is a short popular introduction to why defining human values precisely enough for a superhuman AI is so hard. In 2022 he left FHI to co-found Aligned AI with Rebecca Gorman, a benefit corporation built around 'value extrapolation', the idea that getting AIs to extend human values correctly to new situations is central to alignment; the company has developed methods such as ACE and EquitAI. He continues to publish on the Alignment Forum and EA Forum, including 2026 posts on value generalisation as a theory of change.", "key_ideas": ["value extrapolation / value generalisation", "oracle AI and boxing", "utility indifference and corrigibility", "learning human preferences despite irrationality", "existential risk and space expansion"], "key_works": [{"title": "Smarter Than Us: The Rise of Machine Intelligence", "year": 2014, "url": "https://smarterthan.us/"}, {"title": "Value generalisation Theory of Change: putting it into practice (EA Forum)", "year": 2026, "url": "https://forum.effectivealtruism.org/posts/DCgDArFEioeqmmNvN/value-generalisation-theory-of-change-putting-it-into"}, {"title": "The dangers in algorithms learning humans’ values and irrationalities (with R. Gorman)", "year": 2022, "url": "https://arxiv.org/html/2202.13985v2"}], "quotes": [{"text": "If we don’t get whacked by the existential risks, the future is probably going to be wonderful.", "context": "Singularity 1on1 podcast interview with Nikola Danaylov (2014), highlighted quote", "source_url": "https://www.singularityweblog.com/stuart-armstrong-existential-risks/"}, {"text": "AI that can run 1,000 times faster than humans can earn 1,000 times more than people. It can make 100 copies of itself.", "context": "Quoted in Computer Weekly (June 2015)", "source_url": "https://www.computerweekly.com/news/4500248762/The-rise-of-general-purpose-AI-and-its-threat-to-humanity"}, {"text": "I'm leaving the Future of Humanity Institute, the best and most impactful job I've ever had, to co-found Aligned AI. For the first time in my research career, I feel the problem of AI alignment is solvable.", "context": "LessWrong post 'Why I'm co-founding Aligned AI' (17 Feb 2022), archived PDF", "source_url": "https://pdf.stafforini.com/armstrong-2022-why-cofounding-aligned.pdf"}, {"text": "The history of AI safety is littered with failures and partial successes. The most common examples of failure are ideas that would work well typically, but which fail in extreme situations - and a superintelligent AI is perfectly capable of creating such situations.", "context": "Same post (2022)", "source_url": "https://pdf.stafforini.com/armstrong-2022-why-cofounding-aligned.pdf"}], "interviews": [{"title": "Smarter than Us – the Rise of Machine Intelligence: Stuart Armstrong on AI Risk & his book", "outlet": "Science, Technology & the Future (YouTube)", "year": 2015, "url": "https://www.youtube.com/watch?v=RotShnjrmwI", "youtube_id": "RotShnjrmwI"}, {"title": "Stuart Armstrong: The future is going to be wonderful [If we don't get whacked]", "outlet": "Singularity 1on1 (Singularity Weblog)", "year": 2014, "url": "https://www.singularityweblog.com/stuart-armstrong-existential-risks/"}, {"title": "Innovator Coffee EP-41 Beyond Guardrails: Can AI Learn Human Judgement", "outlet": "Innovator Coffee (Substack/YouTube)", "year": 2026, "url": "https://wickey.substack.com/p/innovator-coffee-ep-41-beyond-guardrails"}], "links": {"website": "https://buildaligned.ai/about-us", "x": "", "scholar": "", "wikipedia": "", "github": "", "substack": "", "alignment_forum": "https://www.alignmentforum.org/users/stuart_armstrong"}, "p_doom_or_stance": "Believes the challenge of getting AIs to follow human values 'not only must be solved, but can be solved, and will be solved' (Aligned AI bio); in Oct 2025 said he had become somewhat more positive about LLMs leading to aligned AGI.", "honours": [], "photo": ""}, {"slug": "yuval-noah-harari", "name": "Yuval Noah Harari", "category": "pioneer-public-voice", "current_role": "Historian and Professor, Department of History, Hebrew University of Jerusalem; co-founder of Sapienship (as of 2026)", "orgs_history": ["Lecturer/Professor, Hebrew University of Jerusalem", "Distinguished Research Fellow, Centre for the Study of Existential Risk, Cambridge (per his bio)", "Co-founder, Sapienship (social-impact company)"], "country": "Israel", "known_for": "Bestselling historian ('Sapiens', 'Homo Deus', 'Nexus') who argues AI is 'an agent, not a tool' that has 'hacked the operating system of human civilisation'.", "bio": "Yuval Noah Harari (born 1976) is an Israeli historian at the Hebrew University of Jerusalem whose books 'Sapiens' (2011), 'Homo Deus' (2016), '21 Lessons for the 21st Century' (2018) and 'Nexus' (2024) have sold tens of millions of copies. Since 'Homo Deus' he has warned that algorithms could understand humans better than we understand ourselves and erode liberal democracy. In an April 2023 Economist essay he argued that by mastering language, AI 'has hacked the operating system of human civilisation', called it a new weapon of mass destruction for 'our mental and social world', and urged rigorous safety checks before powerful AI tools are released, comparing it to drug testing. He signed the 2023 FLI pause letter. 'Nexus' (2024) frames AI as the first technology that can make decisions and create ideas by itself, an 'alien intelligence', and warns that information networks optimised for engagement threaten democracy. In his 2026 Tanner Lecture at Oxford he repeated that 'AI is not a tool' but 'an agent with its own hands', and has called for international cooperation to slow an unregulated AI race.", "key_ideas": ["AI as agent, not tool", "AI hacking language and culture ('the operating system of civilisation')", "safety checks before release (pharma analogy)", "threats to democracy and information networks", "need for global cooperation and trust"], "key_works": [{"title": "Homo Deus: A Brief History of Tomorrow", "year": 2016, "url": "https://www.ynharari.com/book/homo-deus/"}, {"title": "Yuval Noah Harari argues that AI has hacked the operating system of human civilisation (The Economist)", "year": 2023, "url": "https://www.economist.com/by-invitation/2023/04/28/yuval-noah-harari-argues-that-ai-has-hacked-the-operating-system-of-human-civilisation"}, {"title": "Nexus: A Brief History of Information Networks from the Stone Age to AI", "year": 2024, "url": "https://www.ynharari.com/book/nexus/"}], "quotes": [{"text": "We now have to grapple with a new weapon of mass destruction that can annihilate our mental and social world. We can still regulate the new ai tools, but we must act quickly. Whereas nukes cannot invent more powerful nukes, ai can make exponentially more powerful ai.", "context": "'Yuval Noah Harari argues that AI has hacked the operating system of human civilisation', The Economist By Invitation (28 April 2023); archived copy", "source_url": "https://www.cbhs-sacramento.org/wp-content/uploads/Yuval-Noah-Harari-argues-that-AI-has-hacked-the-operating-system-of-human-civilisation_ByInvitation_Economist.pdf"}, {"text": "The first crucial step is to demand rigorous safety checks before powerful ai tools are released into the public domain.", "context": "Same Economist essay (2023)", "source_url": "https://www.cbhs-sacramento.org/wp-content/uploads/Yuval-Noah-Harari-argues-that-AI-has-hacked-the-operating-system-of-human-civilisation_ByInvitation_Economist.pdf"}, {"text": "Now the most important thing to know about AI is that AI is not a tool. It’s not a tool in our hands. It is an agent with its own hands.", "context": "Tanner Lecture on Human Values, University of Oxford (2026), transcript", "source_url": "https://singjupost.com/transcript-ai-has-hacked-the-code-of-human-civilization-yuval-noah-harari/"}], "interviews": [{"title": "AI and the future of humanity (Frontiers Forum)", "outlet": "Frontiers Forum Live (YouTube)", "year": 2023, "url": "https://www.youtube.com/watch?v=LWiM-LuRe6w", "youtube_id": "LWiM-LuRe6w"}, {"title": "#390 – Yuval Noah Harari: Human Nature, Intelligence, Power, and Conspiracies", "outlet": "Lex Fridman Podcast", "year": 2023, "url": "https://lexfridman.com/yuval-noah-harari/"}, {"title": "AI Has Hacked The Code Of Human Civilization (Tanner Lecture, transcript)", "outlet": "University of Oxford / The Singju Post", "year": 2026, "url": "https://singjupost.com/transcript-ai-has-hacked-the-code-of-human-civilization-yuval-noah-harari/"}, {"title": "'Sapiens' Author Yuval Noah Harari on AI's Promise and Peril", "outlet": "The Wall Street Journal", "year": 2025, "url": "https://www.wsj.com/tech/ai/ai-yuval-noah-harari-18f82d7d"}], "links": {"website": "https://www.ynharari.com/", "x": "https://x.com/harari_yuval", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Yuval_Noah_Harari", "github": "", "substack": ""}, "p_doom_or_stance": "Treats AI as a civilisational-scale risk (to democracy and human agency) and calls for safety checks, regulation and international cooperation; no numeric estimate.", "honours": ["Polonsky Prize for Creativity and Originality (2009, 2012)", "Moncado Award, Society for Military History (2011)"], "photo": "yuval-noah-harari.jpg"}, {"slug": "brian-christian", "name": "Brian Christian", "category": "pioneer-public-voice", "current_role": "Research Fellow, Center for Human-Compatible AI (CHAI), UC Berkeley (2026–present); DPhil, University of Oxford (2023–2026)", "orgs_history": ["Doctoral researcher, Human Information Processing Lab, Oxford (Clarendon Scholar, 2023–2026)", "Affiliate, CHAI, UC Berkeley (2020–)", "Member, AI Policy and Governance Working Group, Institute for Advanced Study (2023–25)", "Visiting scholar, Simons Institute (2020)"], "country": "United States", "known_for": "Author of 'The Alignment Problem' (2020), the most widely read popular book on AI alignment, now an alignment researcher on human preferences and RLHF.", "bio": "Brian Christian (born 1984) is an American author and researcher who studied computer science and philosophy at Brown and poetry at the University of Washington. His books 'The Most Human Human' (2011) and, with Tom Griffiths, 'Algorithms to Live By' (2016) explored what computing reveals about human life. 'The Alignment Problem: Machine Learning and Human Values' (2020), based on interviews with hundreds of researchers, traced the field from algorithmic bias and fairness to reward hacking, inverse reinforcement learning and AI safety; the New York Times wrote that if you read one book on AI, 'this is the one'. In 2023 he began a DPhil in experimental psychology at Oxford as a Clarendon Scholar, supervised by Christopher Summerfield and Jakob Foerster, with a 2026 thesis titled 'What Humans Want: Models of Preference, Choice, and Reward in Minds and Machines', studying reward models and RLHF as incomplete tools for capturing human values. In 2026 he became a Research Fellow at Berkeley's Center for Human-Compatible AI.", "key_ideas": ["the alignment problem as gap between intention and outcome", "reward hacking / specification gaming", "inverse reinforcement learning and learning from human feedback", "computational models of human preferences", "fairness and representation in ML"], "key_works": [{"title": "The Alignment Problem: Machine Learning and Human Values", "year": 2020, "url": "https://brianchristian.org/the-alignment-problem/"}, {"title": "Algorithms to Live By (with Tom Griffiths)", "year": 2016, "url": "https://brianchristian.org/"}, {"title": "What Humans Want: Models of Preference, Choice, and Reward in Minds and Machines (DPhil thesis)", "year": 2026, "url": "https://brianchristian.org/research/"}], "quotes": [{"text": "If you had an ostensible basketball-playing agent that you rewarded for getting a high score, a reasonably intelligent basketball agent would learn to get good at basketball, but a superintelligent basketball playing agent would learn that the score is just some electrical current flowing through the scoreboard, and so it would learn to like re-solder its scoreboard and just make it say ‘9,999,’ or whatever.", "context": "80,000 Hours podcast (2021), on reward hacking", "source_url": "https://80000hours.org/podcast/episodes/brian-christian-the-alignment-problem/"}, {"text": "So the exact same architecture is being used by Facebook to essentially play us. We are the Atari game in that situation.", "context": "Same 80,000 Hours episode, on DQN in recommender systems", "source_url": "https://80000hours.org/podcast/episodes/brian-christian-the-alignment-problem/"}, {"text": "The alignment problem is essentially about how we get machines to behave in accordance with human norms and human values.", "context": "University of Oxford Q&A (2024)", "source_url": "https://www.alumni.ox.ac.uk/article/brian-christian", "unverified": true}], "interviews": [{"title": "Brian Christian on the alignment problem", "outlet": "80,000 Hours", "year": 2021, "url": "https://80000hours.org/podcast/episodes/brian-christian-the-alignment-problem/"}, {"title": "Can we truly align AI with human values? (Q&A)", "outlet": "University of Oxford Alumni", "year": 2024, "url": "https://www.alumni.ox.ac.uk/article/brian-christian"}, {"title": "AI Alignment with Brian Christian of 'The Alignment Problem'", "outlet": "The {Closed} Session (Super{set})", "year": 2023, "url": "https://www.superset.com/theclosedsession/season-4-episode-7-ai-alignment-with-brian-christian-of-the-alignment-problem"}, {"title": "The Human Implications of AI with Brian Christian (Q&A)", "outlet": "National Academies", "year": 2023, "url": "https://www.nationalacademies.org/news/the-human-implications-of-ai-with-brian-christian"}, {"title": "Episode 80: Brian Christian", "outlet": "unSILOed Podcast (Greg LaBlanc)", "year": 2021, "url": "https://www.unsiloedpodcast.com/episodes/episode-80"}], "links": {"website": "https://brianchristian.org/", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Brian_Christian", "github": "", "substack": ""}, "p_doom_or_stance": "", "honours": ["Clarendon Scholarship (2023–26)", "Trappes Exhibition thesis prize, Lincoln College, Oxford (2026)", "The Alignment Problem: finalist, Los Angeles Times Book Prize"], "photo": "brian-christian.jpg"}, {"slug": "ian-hogarth", "name": "Ian Hogarth", "category": "governance-policy", "current_role": "Chair, UK AI Security Institute (since June 2023; still chair as of July 2026); co-founder and partner, Plural", "orgs_history": ["Chair, UK Foundation Model Taskforce / Frontier AI Taskforce (2023)", "Co-founder and CEO, Songkick (2007–)", "Co-founder, Plural Platform (2021)", "Co-author, annual State of AI Report (2018–)"], "country": "United Kingdom", "known_for": "Investor whose 2023 FT essay 'We must slow down the race to God-like AI' led to his appointment as founding chair of the UK's AI Safety (now Security) Institute.", "bio": "Ian Hogarth is a British entrepreneur and investor who studied information engineering and machine learning at Cambridge. He co-founded the concert-discovery company Songkick in 2007, co-founded the founder-led fund Plural in 2021, backed more than 50 AI start-ups, and since 2018 has co-authored the annual State of AI Report. In April 2023 he wrote a widely read Financial Times essay, 'We must slow down the race to God-like AI', arguing that a race among a few companies towards AGI risked a force 'beyond our control or understanding' and proposing that the most dangerous research be moved into a CERN-like 'Island'. Two months later Prime Minister Rishi Sunak appointed him chair of the Foundation Model Taskforce, which became the AI Safety Institute at the November 2023 Bletchley Park summit and was renamed the AI Security Institute in February 2025. He divested holdings in frontier-model companies, including his Anthropic stake, on taking the role. As chair he has overseen AISI's growth into what the NYT and The Economist described as the world's leading government AI-testing body, and in 2026 publicly warned against reorganisations that drive talent out of government.", "key_ideas": ["slowing the race to 'God-like AI'", "state capacity for frontier-AI evaluation", "CERN-like 'Island' for dangerous AGI research", "present and future AI harms should be tackled together"], "key_works": [{"title": "We must slow down the race to God-like AI (Financial Times)", "year": 2023, "url": "https://www.ft.com/content/03895dc4-a3b7-481e-95cc-336a524f2ac2"}, {"title": "State of AI Report (co-author, annual)", "year": 2025, "url": "https://www.stateof.ai/"}], "quotes": [{"text": "God-like AI could be a force beyond our control or understanding, and one that could usher in the obsolescence or destruction of the human race.", "context": "'We must slow down the race to God-like AI', Financial Times (13 April 2023), as quoted by Longreads", "source_url": "https://longreads.com/2023/04/14/we-must-slow-down-the-race-to-god-like-ai/"}, {"text": "Those of us who are concerned see two paths to disaster. One harms specific groups of people and is already doing so. The other could rapidly affect all life on Earth.", "context": "Same FT essay (2023), excerpt published by Longreads", "source_url": "https://longreads.com/2023/04/14/we-must-slow-down-the-race-to-god-like-ai/"}, {"text": "Even so, the risks of continuing without proper governance are too high.", "context": "Same FT essay (2023), closing section as excerpted on the EA Forum", "source_url": "https://forum.effectivealtruism.org/posts/FdmdsXuAbzwAjTecr/ft-we-must-slow-down-the-race-to-god-like-ai"}, {"text": "The best civil servants I’ve worked with are there to have impact. If you chew their days up with these kind of random re-orgs, the best people move on.", "context": "To City AM on the Burnham government's technology-department shake-up (July 2026)", "source_url": "https://www.cityam.com/burnham-risks-big-mistake-on-ai-with-tech-department-shake-up/"}], "interviews": [{"title": "Ian Hogarth: The 100 Most Influential People in AI 2023 (profile interview)", "outlet": "TIME", "year": 2023, "url": "https://time.com/collections/time100-ai/6309473/ian-hogarth"}, {"title": "A Q&A with Songkick Co-founder & Plural Platform Partner Ian Hogarth", "outlet": "Early Early Stage (Substack)", "year": 2026, "url": "https://earlyearlystage.substack.com/p/a-q-and-a-with-songkick-co-founder"}, {"title": "Burnham risks 'big mistake' on AI with tech department shake-up (comment)", "outlet": "City AM", "year": 2026, "url": "https://www.cityam.com/burnham-risks-big-mistake-on-ai-with-tech-department-shake-up/"}], "links": {"website": "https://www.aisi.gov.uk/about", "x": "https://x.com/soundboy", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Ian_Hogarth", "github": "", "substack": ""}, "p_doom_or_stance": "Argued in 2023 that the race to AGI should be slowed and the riskiest work moved into a CERN-like international 'Island'.", "honours": ["TIME100 Most Influential People in AI (2023)"], "photo": ""}, {"slug": "elizabeth-kelly", "name": "Elizabeth Kelly", "category": "governance-policy", "current_role": "Head of Beneficial Deployments, Anthropic (since March 2025)", "orgs_history": ["Inaugural Director, US AI Safety Institute, NIST (Feb 2024–Feb 2025; renamed CAISI in June 2025)", "Executive Office of the President / White House National Economic Council (2022–24): managed technology and financial-services portfolios incl. AI; a lead drafter of the Oct 2023 AI executive order (per TIME)", "Lecturer in Law, Stanford Law School (2025)"], "country": "United States", "known_for": "Founding director of the US AI Safety Institute, which signed the first government pre-deployment testing agreements with OpenAI and Anthropic.", "bio": "Elizabeth Kelly is an American lawyer and technology policymaker. At the White House National Economic Council she managed technology and financial-services portfolios, covering AI, payments, privacy and data sharing, and was one of the lead drafters of President Biden's October 2023 executive order on AI. In February 2024 she became the inaugural director of the US Artificial Intelligence Safety Institute at NIST, which she built from scratch. Under her the institute signed August 2024 agreements with OpenAI and Anthropic for access to major new models before and after release, conducted joint pre-deployment evaluations with the UK AISI, and launched the International Network of AI Safety Institutes in November 2024. Her guiding line was that 'safety enables trust, which enables adoption, which enables innovation'. She left in February 2025 at the change of administration; the institute was re-established as the Center for AI Standards and Innovation (CAISI) in June 2025. In March 2025 she joined Anthropic as Head of Beneficial Deployments, partnering with nonprofits, governments and social enterprises to use AI for public benefit. TIME named her to its 2024 TIME100 AI list.", "key_ideas": ["safety enables trust, adoption and innovation", "government pre-deployment testing of frontier models", "international network of AI safety institutes", "ecosystem of third-party evaluators"], "key_works": [{"title": "US AISI agreements with Anthropic and OpenAI on safety research, testing and evaluation", "year": 2024, "url": "https://www.nist.gov/news-events/news/2024/08/us-ai-safety-institute-signs-agreements-regarding-ai-safety-research"}], "quotes": [{"text": "Safety enables trust, which enables adoption, which enables innovation. And driving that innovation is really our north star at the AI Safety Institute.", "context": "Washington AI Network interview at the JHU Bloomberg Center (Aug 2024), as reported by Johns Hopkins", "source_url": "https://washingtondc.jhu.edu/news/what-to-know-about-the-u-s-artificial-intelligence-safety-institute"}, {"text": "We really view our role at the Commerce Department as driving and leading U.S. innovation, and safety is a key part of that. Safety enables trust, enables adoption, enables innovation. And that’s why we all get up in the morning and why we think our work is so important.", "context": "Same Washington AI Network interview (Aug 2024), as reported by WHC Insider", "source_url": "https://whcinsider.com/2024/08/26/exclusive-interview-u-s-ai-safety-institutes-elizabeth-kelly-on-u-s-leadership-in-ai-innovation-and-safety"}, {"text": "Safety is essential to, and not at odds with, fueling breakthrough technological innovation. Without safety, consumers will not trust technology or let it into their lives, and a technology like AI can’t go from a novelty to a driver of the economy.", "context": "POLITICO 'Future in Five Questions' (July 2024); seen in search excerpt, page blocked to direct fetch", "source_url": "https://www.politico.com/newsletters/digital-future-daily/2024/07/26/5-questions-for-the-ai-safety-institutes-elizabeth-kelly-00171436", "unverified": true}], "interviews": [{"title": "Interview with US AI Safety Institute Director Elizabeth Kelly", "outlet": "Washington AI Network (YouTube)", "year": 2024, "url": "https://www.youtube.com/watch?v=8ubf8xlKpDc", "youtube_id": "8ubf8xlKpDc"}, {"title": "The U.S. Vision for AI Safety: A Conversation with Elizabeth Kelly", "outlet": "CSIS AI Policy Podcast", "year": 2024, "url": "https://www.csis.org/analysis/us-vision-ai-safety-conversation-elizabeth-kelly-director-us-ai-safety-institute"}, {"title": "Elizabeth Kelly: The 100 Most Influential People in AI 2024", "outlet": "TIME", "year": 2024, "url": "https://time.com/collections/time100-ai-2024/7012783/elizabeth-kelly"}, {"title": "Elizabeth Kelly on risk, innovation and the future of work", "outlet": "Harvard Business School BiGS", "year": 2025, "url": "https://www.hbs.edu/bigs/elizabeth-kelly-artificial-intelligence-future-of-work"}], "links": {"website": "https://www.anthropic.com/", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Elizabeth_Kelly_(official)", "github": "", "substack": ""}, "p_doom_or_stance": "", "honours": ["TIME100 Most Influential People in AI (2024)"], "photo": ""}]);
